mapper.select:
SELECT COUNT(DISTINCT CAST(SALES_ORDER AS UNSIGNED))
FROM BASIL_SBX_PRD.RAW_SYSPRO_INPUT


        CAST(SALES_ORDER AS UNSIGNED) = #{salesOrder}



        AND ORDER_STATUS = #{salesStatus}



        AND CUSTOMER_PO_NUMBER LIKE CONCAT('%', #{poNumber}, '%')



        AND M_STOCK_CODE = #{materialNumber}



        AND M_STOCK_DES LIKE CONCAT('%', #{description}, '%')



        AND SALES_PERSON_NAME LIKE CONCAT('%', #{salesPerson}, '%')



        AND CUSTOMER_NAME LIKE CONCAT('%', #{sysproCustomerName}, '%')



        AND CAST(CUSTOMER AS UNSIGNED) = #{customerId}



        AND M_LINE_SHIP_DATE BETWEEN #{shipFromDate} AND #{shipToDate}



        AND ORDER_DATE BETWEEN #{createFromDate} AND #{createToDate}

SELECT DISTINCT CAST(SALES_ORDER AS UNSIGNED) AS salesOrder, mc.CUSTOMER_ORGANIZATION AS customer, scav.VALUE AS orderStatus, ORDER_DATE AS orderDate, CUSTOMER_PO_NUMBER AS customerPONumber, MO_DESCRIPTION AS description, SPECIAL_INSTRUCTIONS AS specialInstructions, SALES_PERSON_NAME AS salesPerson, CONTACT AS contact, CUSTOMER_NAME AS sysproCustomerName, CONCAT(`SHIP_ADDRESS_1`, ' ', `SHIP_ADDRESS_2`, '\n', `SHIP_ADDRESS_3`, ' ', `SHIP_ADDRESS_4`, ', ', `SHIP_POSTAL_CODE`) AS shipAddress, REQ_SHIP_DATE AS reqShipDate FROM BASIL_SBX_PRD.RAW_SYSPRO_INPUT rsi LEFT JOIN BASIL_ODS_PRD.MASTER_CUSTOMER mc ON CAST(rsi.CUSTOMER AS UNSIGNED) = mc.MC_OID LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scav ON (scav.SYSPRO_CODE = rsi.ORDER_STATUS AND scav.SC_OID = 3)
CAST(SALES_ORDER AS UNSIGNED) = #{salesOrder}
AND ORDER_STATUS = #{salesStatus}
AND CUSTOMER_PO_NUMBER LIKE CONCAT('%', #{poNumber}, '%')
AND M_STOCK_CODE = #{materialNumber}
AND M_STOCK_DES LIKE CONCAT('%', #{description}, '%')
AND SALES_PERSON_NAME LIKE CONCAT('%', #{salesPerson}, '%')
AND CUSTOMER_NAME LIKE CONCAT('%', #{sysproCustomerName}, '%')
AND CAST(CUSTOMER AS UNSIGNED) = #{customerId}
AND M_LINE_SHIP_DATE BETWEEN #{shipFromDate} AND #{shipToDate}
AND ORDER_DATE BETWEEN #{createFromDate} AND #{createToDate}
ORDER BY ${sortColumns}
LIMIT #{offset,jdbcType=INTEGER},#{count,jdbcType=INTEGER}

SELECT CAST(SALES_ORDER_LINE AS UNSIGNED) salesOrderLine, M_STOCK_CODE materialNumber, scavProductClass.VALUE productClass, M_STOCK_DES stockDescription, M_LINE_SHIP_DATE soLineShipDate, N_COMMENT comment, scavLineType.VALUE lineType, scavDocumentType.VALUE documentType, M_ORDER_QTY orderQty, M_SHIP_QTY shippedQty, M_BACK_ORDER_QTY backOrderQty, M_COMMIT_DATE lastRefresh FROM BASIL_SBX_PRD.RAW_SYSPRO_INPUT rsi LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavProductClass ON (scavProductClass.SYSPRO_CODE = rsi.M_PRODUCT_CLASS AND scavProductClass.SC_OID = 6) LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavLineType ON (scavLineType.SYSPRO_CODE = rsi.LINE_TYPE AND scavLineType.SC_OID = 4) LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavDocumentType ON (scavDocumentType.SYSPRO_CODE = rsi.DOCUMENT_TYPE AND scavDocumentType.SC_OID = 5)
CAST(SALES_ORDER AS UNSIGNED) = #{salesOrder}
AND M_STOCK_CODE = #{materialNumber}
AND M_STOCK_DES LIKE CONCAT('%', #{description}, '%')
AND M_LINE_SHIP_DATE BETWEEN #{shipFromDate} AND #{shipToDate}
ORDER BY SALES_ORDER_LINE;
